<section class="mkt-workspace" id="mktReports"><div class="mkt-heading"><div><h2>Tổng quan MKT</h2><p id="mktStatus" role="status">Đang tải báo cáo…</p></div><button id="mktImportOpen" class="primary">Nhập dữ liệu MKT</button><button id="mktRefresh" class="secondary">Làm mới</button></div>
<details class="mkt-filters"><summary>Lọc báo cáo <span id="mktFilterCaption">Hôm nay · Tất cả mã</span></summary><form id="mktFilters"><label>Thời gian<select name="period"></select></label><label>Từ ngày<input type="date" name="from"></label><label>Đến ngày<input type="date" name="to"></label><label>Mã sản phẩm<select name="sku"><option value="">Tất cả mã</option></select></label><label>Chiến dịch / tài khoản<input name="campaign" type="search" placeholder="Tìm theo tên"></label><button class="primary">Áp dụng</button></form></details>
<div class="mkt-kpis" id="mktKpis"></div><div class="mkt-gender" id="mktGender"></div><p class="mkt-alert" id="mktNotice" hidden></p>
<div class="mkt-breakdowns"><section class="mkt-card"><h3>Theo mã sản phẩm</h3><div class="mkt-table-wrap"><table><thead><tr><th>Mã / sản phẩm</th><th>Chi tiêu quảng cáo</th><th>Lượt mua QC</th><th>Đơn BẢNG ĐƠN</th><th>Chi phí / đơn</th></tr></thead><tbody id="mktProducts"></tbody></table></div></section><section class="mkt-card"><h3>Theo chiến dịch</h3><div class="mkt-table-wrap"><table><thead><tr><th>Chiến dịch</th><th>Tài khoản</th><th>Tổng chi tiêu / chi phí</th><th>Lượt mua QC</th></tr></thead><tbody id="mktCampaigns"></tbody></table></div></section></div>
<details class="mkt-card"><summary>Nguồn dữ liệu đã lưu</summary><p class="hint">Các lần nhập được giữ lại. Cùng ngày, tài khoản, chiến dịch và quảng cáo sẽ cập nhật dữ liệu của nhóm đó, không cộng chồng chi tiêu của các lần nhập.</p><div id="mktSources"></div></details><p class="mkt-footnote">Chi phí tổng bằng chi tiêu quảng cáo đã nhập. Chi phí/đơn lấy mỗi dòng có sản phẩm trên BẢNG ĐƠN một lần theo ngày và nhóm của sheet. Đơn nhiều mã được tính trong từng mã; Tổng tính mỗi dòng một lần.</p>
</section>
<dialog id="mktImportDialog" class="mkt-import-dialog"><div class="mkt-dialog-heading"><h2>Nhập dữ liệu MKT</h2><button id="mktImportClose" class="secondary" type="button">Đóng</button></div><div class="mkt-screen-actions"><button id="mktCapture" class="primary" type="button">▣ Chuyển dữ liệu màn hình</button><label>Hoặc chọn ảnh màn hình<input id="mktScreenImage" type="file" accept="image/png,image/jpeg,image/webp"></label></div><p class="hint">Chọn tab / cửa sổ quảng cáo và vùng bảng có hàng tiêu đề. Ảnh được đọc ngay trên trình duyệt; kiểm tra số liệu trước khi lưu.</p><div id="mktCaptureHost" hidden></div><form id="mktUpload"><div class="mkt-import-fields"><label>Ngày dữ liệu nếu bảng không có cột ngày<input type="date" name="date" required></label><label>Excel / CSV<input type="file" name="file" accept=".xlsx,.csv"></label></div><label>Hoặc copy bảng trên máy tính và dán vào đây<textarea name="text" rows="5" placeholder="Dán cả hàng tiêu đề, tên chiến dịch và cột chi tiêu…"></textarea></label><p class="hint">Hỗ trợ .xlsx, .csv và bảng copy/dán. Cần dữ liệu theo từng ngày; không tự chia đều chi tiêu tổng nhiều ngày.</p><button class="primary">Quét dữ liệu</button></form>
<section id="mktMapping" hidden><h3 id="mktSourceName"></h3><form id="mktMapForm"><div class="mkt-import-fields"><label>Sheet dữ liệu<select name="sheet"></select></label><label>Hàng tiêu đề<input name="headerRow" type="number" min="1" max="31" value="1"></label><label>Tài khoản / nguồn (khi không có cột)<input name="account" placeholder="Ví dụ: TKQC 01" maxlength="200"></label><label>Mã dự phòng<select name="default_sku"><option value="">Tự nhận diện từ tên chiến dịch / quảng cáo</option></select></label><label>Đơn vị tiền<select name="currency"><option value="VND">VND</option><option value="other">Ngoại tệ, quy đổi theo tỷ giá nhập</option></select></label><label>Tỷ giá sang VND<input name="exchange" type="number" min="0.000001" step="any" value="1" required></label></div><div id="mktColumnMap" class="mkt-column-map"></div><button class="secondary">Kiểm tra số liệu</button></form><div id="mktPreview"></div><p class="hint">Kiểm tra ngày, chi tiêu và mã sản phẩm trước khi lưu. Những dòng có cùng ngày + tài khoản + chiến dịch + quảng cáo sẽ thay dữ liệu nhóm tương ứng của lần nhập cũ; file gốc vẫn được giữ.</p><button id="mktCommit" class="primary" type="button" disabled>Lưu vào báo cáo</button></section><p id="mktImportStatus" role="status"></p></dialog>
